const CLUSTER_STOP_ZOOM=15;
function routePad(){const r=document.getElementById('routeSection');return ((r&&r.offsetHeight)||46)+36}
function mapFitOptions(extra){return Object.assign({paddingTopLeft:[60,60],paddingBottomRight:[60,routePad()]},extra||{})}
const listingCluster=L.markerClusterGroup?L.markerClusterGroup({showCoverageOnHover:false,zoomToBoundsOnClick:false,spiderfyOnMaxZoom:false,maxClusterRadius:z=>z>=CLUSTER_STOP_ZOOM?1:44,iconCreateFunction:c=>L.divIcon({className:'',html:`<div class="hf-cluster hf-cluster--${state.category==='treats'?'treats':'displays'}" title="${c.getChildCount()} ${state.category==='treats'?'treat stops':'displays'}, click to zoom">${c.getChildCount()}</div>`,iconSize:[36,36]})}):null;
if(listingCluster){map.addLayer(listingCluster);listingCluster.on('clusterclick',e=>{if(map.getZoom()>=CLUSTER_STOP_ZOOM)e.layer.spiderfy();else e.layer.zoomToBounds({padding:[40,40]})})}
function addListing(m){if(listingCluster)listingCluster.addLayer(m);else m.addTo(map)}
function removeListing(m){if(listingCluster){if(listingCluster._spiderfied)listingCluster.unspiderfy();listingCluster.removeLayer(m)}else map.removeLayer(m)}
function hasListing(m){return listingCluster?listingCluster.hasLayer(m):map.hasLayer(m)}

const TREAT_FORM_URL='https://forms.gle/DTuKs27nSUWVbyf1A';
// Pins and card badges are icons only: listing numbers stay internal (links, routes, reviews) and are never shown.
