function stopBadge(pinEl,idx){if(!pinEl)return;pinEl.querySelectorAll('.pin__stop').forEach(e=>e.remove());if(!routeOpen()||idx<0)return;const b=document.createElement('span');b.className='pin__stop';b.textContent=String(idx+1);pinEl.appendChild(b)}
function syncRouteBadges(){markerByNum.forEach((m,n)=>{const el=m.getElement();stopBadge(el&&el.querySelector('.pin'),state.route.findIndex(r=>r.num===n))});eventMarkers.forEach(m=>{const el=m.getElement();stopBadge(el&&el.querySelector('.pin'),state.route.findIndex(r=>r.eventId!=null&&r.eventId===m._evId))})}
function applyPinState(m,n){const pin=m.getElement()&&m.getElement().querySelector('.pin');if(pin){pin.classList.toggle('is-selected',state.selected===n);pin.classList.toggle('is-on-route',state.route.some(r=>r.num===n));stopBadge(pin,state.route.findIndex(r=>r.num===n))}}
function pinHTML(n,kind){return `<div class="pin pin--${kind}" data-pin="${n}"><img class="pin__art" src="assets/icons/v2/pin-${kind==='treat'?'treat-stop':'display'}.svg" alt=""><img class="pin__badge" src="assets/icons/badge-on-route.svg" alt=""></div>`}
function cardIconHTML(kind){return `<div class="pin pin--${kind} pin--card"><img class="pin__art" src="assets/icons/v2/icon-${kind==='treat'?'treat-stop':'display'}.svg" alt=""><img class="pin__badge" src="assets/icons/badge-on-route.svg" alt=""></div>`}
function raiseMarker(m,on){if(!m||!m.setZIndexOffset)return;if(m._hfBase===undefined)m._hfBase=m.options.zIndexOffset||0;m.setZIndexOffset(m._hfBase+(on?1000:0))}
function pinWidth(){return matchMedia('(max-width:767px)').matches?30:34}
function pinHeight(w){return Math.round(w*156/128)}
function iconFor(n,kind){if(kind==='community'){return L.divIcon({className:'community-icon',html:communityPinHTML(n),iconSize:[44,44],iconAnchor:[22,44]})}const w=pinWidth(),h=pinHeight(w);return L.divIcon({className:'',html:pinHTML(n,kind),iconSize:[w,h],iconAnchor:[w/2,h-1]})}
function gmapsDirections(address){return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address)}`}
// Route-planner meta line for event stops: their date + hours, never a town.
function eventDateBits(x){const upcoming=typeof eventUpcomingDates==='function'?eventUpcomingDates(x):[];const dates=upcoming.length?upcoming:(x.date?[x.date]:[]);const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});if(!dates.length){const d=x.date||String(x.startAt||'').slice(0,10);return d&&/^\d{4}-\d{2}-\d{2}$/.test(d)?fmt(d):'Date TBA'}if(dates.length===1)return fmt(dates[0]);return 'Next '+fmt(dates[0])+' · also '+dates.slice(1).map(fmt).join(', ')}
function eventStopDateLine(x){if(x.ongoing)return 'Open all season'+(x.hours?' · '+x.hours:'');return eventDateBits(x)+(x.hours?' · '+x.hours:'')}
function isTreatStop(x){return x.kind==='Trick-or-treat stop'}
// Community-spotted houses (source:"community"): nominated by a visitor, reviewed, then published.
// lat/lng is the curb point in front of the verified address, never the rooftop or the photo's GPS point.
// Records still carry levels/type/features arrays (empty) so every owner-listing filter keeps working.
function isCommunity(x){return !!x&&x.source==='community'}
// "Community spotted" is a rail/filter-sheet toggle, separate from the scare-level chips. Off hides only community pins and cards.
function setCommunity(on){state.community=!!on;const sel=listings.find(v=>v.num===state.selected);if(!state.community&&sel&&isCommunity(sel)){state.selected=null;hidePeek()}}
function removedHere(x){try{return JSON.parse(localStorage.getItem('hfhidden:2026')||'[]').includes(x.num)}catch{return false}}
const COMMUNITY_BADGE='Spotted by the community, not submitted by the owner';
function communityNameText(x){return String(x.name||'')}
function communityPinHTML(n,cls){return `<div class="pin pin--community${cls?' '+cls:''}" data-pin="${n}"><img class="pin__art" src="assets/pins/pin-community.svg" alt=""><img class="pin__art pin__art--route" src="assets/pins/pin-community-route.svg" alt=""><span class="pin__cnum${n>99?' pin__cnum--wide':''}">${n}</span></div>`}
const communityOpen=new Set();
function communityDetailsHTML(x){const why=String(x.notes||'').trim(),photo=x.photo&&/^https:\/\//.test(x.photo)?`<div class="community__photo"><img src="${safeListingText(x.photo)}" alt="Street view of ${safeListingText(x.name)}" loading="lazy"></div>`:'',by=x.spottedBy?`<span class="community__by">Spotted by ${safeListingText(x.spottedBy)}</span>`:'';return `${photo}${why?`<p class="community__why">“${safeListingText(why)}”</p>`:''}${by}<div class="community__badge"><span class="community__badge-dot" aria-hidden="true"></span>${COMMUNITY_BADGE}</div><a class="community__claim" href="claim.html?id=${x.num}">Is this your house? Claim it or remove it</a>`}
function communityBodyHTML(x,peek){const addr=safeListingText(x.address.replace(/,\s*NJ\s*$/i,'')),hours=typeof listingHoursText==='function'?listingHoursText(x):'',onRoute=state.route.some(r=>r.num===x.num);return `<div class="community__head"><div class="card__pin card__pin--community">${communityPinHTML(x.num,'pin--card')}</div><div class="card__heading"><h3 class="card__name"><span class="card__nametext" data-card-name="${x.num}">${safeListingText(communityNameText(x))}</span></h3></div></div><div class="card__addrline"><a class="card__address" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener" aria-label="Directions to ${safeListingText(x.name)}">${addr} ↗</a></div>${hours?`<p class="card__hours">${safeListingText(hours)}</p>`:''}<div class="community__actions"><button class="community__route" type="button" ${peek?`data-peek-route="${x.num}"`:`data-route="${x.num}"`} aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button></div><div class="community__expand">${communityDetailsHTML(x)}</div>`}
function communityCardHTML(x){const selected=state.selected===x.num,onRoute=state.route.some(r=>r.num===x.num),open=communityOpen.has(x.num),levels=Array.isArray(x.levels)?x.levels:[],type=Array.isArray(x.type)?x.type:[],features=Array.isArray(x.features)?x.features:[];return `<article class="card card--compact card--community ${selected?'is-selected':''}${onRoute?' card--on-route':''}${open?' is-open':''}" data-card="${x.num}" data-community="1" data-town="${safeListingText(x.town)}" tabindex="0" aria-expanded="${open}" aria-label="Community-spotted display: ${safeListingText(x.name)}"><div class="card__head"><div class="card__pin">${cardIconHTML('display')}</div><div class="card__heading"><h3 class="card__name"><span class="card__nametext" data-card-name="${x.num}">${safeListingText(communityNameText(x))}</span></h3></div></div>${listingStatusHTML(x)}<div class="card__addrline"><a class="card__address" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener" aria-label="Directions to ${safeListingText(x.name)}">${safeListingText(x.address.replace(/,\s*NJ\s*$/i,''))} ↗</a>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}</div><div class="card__hours-row"><p class="card__hours">${safeListingText(typeof listingHoursText==='function'?listingHoursText(x):'')}</p><button type="button" class="community__toggle" data-community-toggle="${x.num}" aria-expanded="${open}">Details</button></div>${levels.length?`<p class="card__scare-row"><span class="card__scare">${scarePips(levels)}</span></p>`:''}${(type.length||features.length)?`<div class="card__tags">${type.map(t=>hfTagHTML(t,'chip--type')).join('')}${features.map(featureChip).join('')}</div>`:''}<div class="card__actions"><button class="btn card__route-btn" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button><button type="button" class="card__mapbtn" data-card-map="${x.num}"><span aria-hidden="true">◉</span> Map</button><button type="button" class="card__morebtn" data-card-more="${x.num}" aria-expanded="false" aria-label="More for ${safeListingText(x.name)}">⋯</button><div class="card__meta"><div class="card__meta-left"><a class="card-rating" href="${listingPageHref(x)}#feedback" data-rating-summary="${x.num}" aria-label="View ratings for ${safeListingText(x.name)}"><span class="card-rating__text">No ratings yet · <span class="card-rating__rate">Rate</span></span></a></div><div class="card__meta-right"><a class="card__metalink" href="${listingPageHref(x)}#report-update">Report</a><a class="card__metalink" href="${listingPageHref(x)}#share">Share</a></div></div></div><div class="community__expand"${open?'':' hidden'}>${communityDetailsHTML(x)}</div></article>`}
function toggleCommunityCard(n){if(communityOpen.has(n))communityOpen.delete(n);else communityOpen.add(n);const card=document.querySelector(`[data-card="${n}"]`);if(!card)return;const open=communityOpen.has(n);card.classList.toggle('is-open',open);card.setAttribute('aria-expanded',String(open));const panel=card.querySelector('.community__expand');if(panel)panel.hidden=!open;const btn=card.querySelector('[data-community-toggle]');if(btn)btn.setAttribute('aria-expanded',String(open))}
function eventIsUpcoming(x,now){if(x&&x.ongoing===true)return true;if(typeof eventHasUpcoming==='function')return eventHasUpcoming(x,now==null?new Date():now);return new Date(x.endAt).getTime()>(now==null?Date.now():+new Date(now))}
function matchFilter(x){if(!inCurrentSeason(x))return false;if(x.hidden||removedHere(x))return false;if(isCommunity(x)&&!state.community)return false;if(x.placeholder)return state.category==='displays'&&state.filter==='All'&&(typeof isDefaultArea!=='function'||!state.search||isDefaultArea(state.search));if(state.category==='events')return false;if(state.dateFilter&&state.dateFilter.kind&&typeof schedulesDateMatch==='function'&&!schedulesDateMatch(x,state.dateFilter))return false;if(state.search&&typeof inSearchArea==='function'&&!inSearchArea(x,state.search))return false;if(isTreatStop(x)!==(state.category==='treats'))return false;if(Array.isArray(state.features)&&state.features.length&&!state.features.every(f=>(x.features||[]).some(xf=>featureKey(xf)===f)))return false;if(state.category==='treats')return !state.categoryFeature||(x.features||[]).includes(state.categoryFeature);if(state.filter==='All')return true;if(['Family Friendly','Spooky','Scary'].includes(state.filter))return x.levels.includes(state.filter);if(['Walk-through','Drive-by','Walk-by','Drive or walk by (both)'].includes(state.filter))return x.type.includes(state.filter)||(x.type.includes('Drive or walk by (both)')&&['Drive-by','Walk-by'].includes(state.filter));return x.features.some(f=>featureKey(f)===state.filter)}
function matchingEvents(ignoreDay){const onDay=x=>typeof eventOccursOn==='function'?eventOccursOn(x,state.eventDay):(x.date||String(x.startAt||'').slice(0,10))===state.eventDay;const filtered=events.filter(x=>eventIsUpcoming(x)&&inCurrentSeason(x)&&(state.filter==='All'||x.eventType===state.filter)&&(!state.categoryFeature||(x.features||[]).includes(state.categoryFeature))&&(!(state.features&&state.features.length)||state.features.every(f=>(x.features||[]).includes(f)))&&((ignoreDay||!state.eventDay)||x.ongoing||onDay(x))&&(!state.search||typeof inSearchArea!=='function'||inSearchArea(x,state.search))&&(x.ongoing||!state.dateFilter||!state.dateFilter.kind||typeof eventDateMatch!=='function'||eventDateMatch(x,state.dateFilter)));const day=ignoreDay?'':(state.eventDay||'');return typeof sortEventsByStart==='function'?sortEventsByStart(filtered,day):filtered.slice().sort((a,b)=>String(a.startAt||a.date||'').localeCompare(String(b.startAt||b.date||'')))}
// Single source of truth for the ordered visible set. Falls back to number
// order during the very first render, before location.js has loaded.
function activeListings(){return typeof visibleSet==='function'?visibleSet({items:listings,search:state.search,predicate:matchFilter,keepUnlocated:true}):listings.filter(matchFilter)}
function distanceLabelHTML(x){if(!state.search||typeof haversineMi!=='function'||typeof formatDistance!=='function'||!Number.isFinite(x.lat)||!Number.isFinite(x.lng))return '';return `<span class="card__distance">${safeListingText(formatDistance(haversineMi(state.search,x)))} mi</span>`}
function geoEmptyState(){if(!state.search||typeof isDefaultArea!=='function'||typeof nextRadius!=='function')return null;const boundsSearch=state.search.mode==='area'&&state.search.bounds;if(!boundsSearch&&(isDefaultArea(state.search)||state.search.radius==='all'))return null;const r=state.search.radius,next=boundsSearch?null:nextRadius(r);const headline=boundsSearch||state.search.mode==='area'?'Nothing in this map area yet.':state.search.mode==='device'?`Nothing within ${r} miles of your location yet.`:`Nothing within ${r} miles of ${state.search.zip} yet.`;return {headline,next}}
function wireEmptyAction(geoEmpty,formUrl){const btn=document.getElementById('emptyActionBtn');if(!btn)return;btn.hidden=false;if(geoEmpty.next){btn.textContent=`Expand to ${geoEmpty.next} miles`;btn.onclick=()=>document.dispatchEvent(new CustomEvent('hf:expand-radius',{detail:{radius:geoEmpty.next}}))}else{btn.textContent='Add a listing in your area';btn.onclick=()=>window.open(formUrl,'_blank','noopener')}}
// Radius circle for the current search area, in the site palette.
let searchCircle=null;
let openTonightOK=false;
// v7: there is no search-radius circle on the map at any width; this only clears one if present.
function syncSearchCircle(){if(typeof L==='undefined'||!map)return;if(searchCircle){map.removeLayer(searchCircle);searchCircle=null}}
// 1A Phase F (spec 8.7/9.5): events ON THE ROUTE render as purple skull pins
// on the Displays and Treat stops maps. They track route membership (never the
// count/list logic) and are rebuilt whenever the route changes, since every
// membership change flows through renderCards → syncEventPins.
const eventMarkers=[];
function selectEventCard(id){const card=document.querySelector(`#cardList [data-event="${CSS.escape(id)}"]`);document.querySelectorAll('#cardList [data-event]').forEach(c=>c.classList.toggle('is-selected',c===card));eventMarkers.forEach(mm=>{mm.getElement()&&mm.getElement().querySelector('.pin')&&mm.getElement().querySelector('.pin').classList.toggle('is-selected',mm._evId===id);raiseMarker(mm,mm._evId===id)});if(!card)return;const panel=card.closest('.list-column');if(panel&&panel.scrollHeight>panel.clientHeight){const pb=panel.getBoundingClientRect(),cb=card.getBoundingClientRect();panel.scrollTo({top:Math.max(0,panel.scrollTop+cb.top-pb.top-Math.max(0,(panel.clientHeight-cb.height)/2)),behavior:'smooth'})}}
function eventSquareIcon(n){const w=pinWidth(),h=pinHeight(w);return L.divIcon({className:'',html:`<div class="pin pin--event" data-event-pin="${n}"><img class="pin__art" src="assets/icons/v2/pin-event.svg" alt=""></div>`,iconSize:[w,h],iconAnchor:[w/2,h-1]})}
function eventIcon(){return eventSquareIcon(0)}
function syncEventPins(){eventMarkers.forEach(m=>map.removeLayer(m));eventMarkers.length=0;if(state.category==='events'){matchingEvents().filter(ev=>Number.isFinite(ev.lat)&&Number.isFinite(ev.lng)).forEach((ev,i)=>{const m=L.marker([ev.lat,ev.lng],{icon:eventSquareIcon(i+1),keyboard:true,title:`Event: ${ev.name}`,zIndexOffset:900}).addTo(map);m.getElement()?.setAttribute('aria-label',`Event: ${ev.name}`);m._evId=ev.id;m.on('add',()=>stopBadge(m.getElement()&&m.getElement().querySelector('.pin'),state.route.findIndex(r=>r.eventId!=null&&r.eventId===ev.id)));m.on('click',()=>selectEventCard(ev.id));m.on('mouseover',()=>linkEvent(ev.id,true));m.on('mouseout',()=>linkEvent(ev.id,false));eventMarkers.push(m)});if(eventMarkers.length&&!(document.querySelector('.map-frame')||{}).hidden)map.fitBounds(L.featureGroup(eventMarkers).getBounds(),mapFitOptions({maxZoom:14,animate:false}));return}state.route.filter(r=>r.eventId!=null).forEach(r=>{const ev=events.find(x=>x.id===r.eventId);if(!ev||!Number.isFinite(ev.lat)||!Number.isFinite(ev.lng))return;const m=L.marker([ev.lat,ev.lng],{icon:eventIcon(),keyboard:true,title:`Event: ${ev.name}`,zIndexOffset:900}).addTo(map);m.getElement()?.setAttribute('aria-label',`Event: ${ev.name}`);m.on('click',()=>{if(typeof openEvent==='function')openEvent(ev.id)});eventMarkers.push(m)})}
document.addEventListener('hf:search-changed',e=>{state.search=e.detail;renderCards();renderRoute();renderPeek(state.selected);syncSearchCircle();if(searchCircle){map.fitBounds(searchCircle.getBounds().pad(0.12));setTimeout(()=>map.invalidateSize(),100)}if(e.detail&&e.detail.mode==='device'&&Number.isFinite(e.detail.lat)&&Number.isFinite(e.detail.lng))map.flyTo([e.detail.lat,e.detail.lng],12);else if(e.detail&&e.detail.radius==='all'&&!(e.detail.mode==='area'&&e.detail.bounds))fitVisiblePins()});

const FEATURE_ICONS={
 'Costumes Available':{label:'Costumes Available',path:'M10 5a2 2 0 1 1 3 2l-1 1v3M12 11 2 18v3h20v-3Z'},
 'Music/Sound':{label:'Music / Sound',path:'M9 18V5l11-2v13M9 8l11-2M9 18c0 2-5 3-5 0s5-3 5 0m11-2c0 2-5 3-5 0s5-3 5 0'},
 'Photo Opportunities':{label:'Photo opportunities',path:'M3 7h5l2-3h4l2 3h5v14H3ZM16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0'},
 'Fog':{label:'Fog',path:'M3 9h18M5 13h14M2 17h20M7 5h10M5 21h14'},
 'Lights':{label:'Lights',path:'M8 16c-6-6-1-13 4-13s10 7 4 13ZM9 20h6M10 23h4M12 1v1M2 8l2 1m16 0 2-1'},
 'Animatronics':{label:'Animatronics',path:'M6 7h12v13H6ZM12 3v4M8 11h1m6 0h1M9 16h6M3 10v6m18-6v6M8 20v3m8-3v3'},
 'Actors':{label:'Live Actors',path:'M3 4l9 2v12c-7 0-9-7-9-14ZM12 6l9-2c0 7-2 14-9 14M6 9h2m8 0h2M7 13l2 1m6 0 2-1'},
 'Spider theme':{label:'Spider theme',path:'M15 13a3 4 0 1 1-6 0 3 4 0 0 1 6 0M12 6v3M9 10 5 7 2 4m13 6 4-3 3-3M9 12H4l-2-2m13 2h5l2-2M9 14l-5 2-2 4m13-6 5 2 2 4M10 16l-3 3v4m7-7 3 3v4'},
 'Spooky Decor':{label:'Spooky decor',path:'M5 21V9a7 7 0 0 1 14 0v12l-4-2-3 2-3-2ZM8 9h1m6 0h1M10 14h4'},
 'Yard Display':{label:'Yard display',path:'M3 21V8l3-4 3 4v13m6 0V8l3-4 3 4v13M3 11h18M3 17h18'}
};
function featureKey(value){const f=String(value).trim().toLowerCase().replace(/\s*\/\s*/g,'/');if(f==='live actors')return 'Actors';return Object.keys(FEATURE_ICONS).find(k=>k.toLowerCase().replace(/\s*\/\s*/g,'/')===f)||value}
function featureIcon(value){const item=FEATURE_ICONS[featureKey(value)];return item?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${item.path}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`:''}
function featureChip(value){return hfTagHTML(featureKey(value)===value?value:(FEATURE_ICONS[featureKey(value)]||{label:value}).label)}
function scarePips(levels){const order=['Family Friendly','Spooky','Scary'],top=order.filter(x=>levels.includes(x)).pop()||'';return `<span class="pips" title="${safeListingText(levels.length?levels.join(' · '):'Not specified')}">${order.map(x=>`<span class="pip ${levels.includes(x)?'is-on':''}"></span>`).join('')}</span>${safeListingText(top||'Not specified')}`}
function listingStatusHTML(x){if(!['temporarily_closed','weather_cancelled'].includes(x.status))return '';if(x.statusUntil&&new Date(x.statusUntil).getTime()<Date.now())return '';return `<div class="listing-status" role="note"><strong>${x.status==='weather_cancelled'?'Weather cancellation':'Temporarily closed'}</strong>${x.statusNote?`<span>${safeListingText(x.statusNote)}</span>`:''}${x.statusUntil?`<small>Through ${safeListingText(new Date(x.statusUntil).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</small>`:''}<small>Check the host’s updates before visiting.</small></div>`}
function safeListingText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function listingUpdatedHTML(x){if(!x.updatedAt)return '';const date=new Date(x.updatedAt+'T12:00:00');if(Number.isNaN(date.getTime()))return '';return `<p class="listing-updated">Listing updated <time datetime="${safeListingText(x.updatedAt)}">${date.toLocaleDateString(undefined,{dateStyle:'medium'})}</time></p>`}
// Card Rate/Report/Share open the listing page sections (page-first plan
// step 5); reused slots keep their entity, like every listing deep link.
function listingPageHref(x){return 'listing.html?id='+x.num+(isReusedSlot(x)?'&entity='+encodeURIComponent(x.entityId):'')}
function treatDateText(x){const m=/^([A-Za-z]+) (\d{1,2}), (\d{4})$/.exec(String(x.dates||'').trim());if(!m)return x.dates||'';const d=new Date(`${m[1]} ${m[2]}, ${m[3]} 12:00:00`);if(isNaN(d))return x.dates;return d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}
function treatHoursText(x){const t=[treatDateText(x),x.times?compactTime(x.times):''].filter(Boolean).join(' · ');return t||listingHoursText(x)}
function hasHostNotes(x){const n=String((x&&x.notes)||'').trim();return !!n&&!/^more details coming soon\.?$/i.test(n)}
function treatCardHTML(x){const onRoute=state.route.some(r=>r.num===x.num);return `<article class="card card--compact treat-stop-card ${state.selected===x.num?'is-selected':''}${onRoute?' card--on-route':''}" data-card="${x.num}" data-town="${safeListingText(x.town)}" tabindex="0" aria-label="${safeListingText(x.name)}"><div class="card__head"><div class="card__pin">${cardIconHTML('treat')}</div><div class="card__heading"><h3 class="card__name"><span class="card__nametext" data-card-name="${x.num}">${safeListingText(x.name)}</span></h3></div></div>${listingStatusHTML(x)}<div class="card__addrline"><a class="card__address" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener" aria-label="Directions to ${safeListingText(x.name)}">${safeListingText(x.address.replace(/,\s*NJ\s*$/i,''))} ↗</a>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}</div><p class="card__hours">${safeListingText(treatHoursText(x))}</p>${(x.features||[]).length?`<div class="chips">${x.features.map(v=>hfTagHTML(v)).join('')}</div>`:''}<div class="card__actions"><button class="btn card__route-btn" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button><button type="button" class="card__mapbtn" data-card-map="${x.num}"><span aria-hidden="true">◉</span> Map</button><button type="button" class="card__morebtn" data-card-more="${x.num}" aria-expanded="false" aria-label="More for ${safeListingText(x.name)}">⋯</button><div class="card__meta"><div class="card__meta-right"><a class="card__metalink" href="${listingPageHref(x)}#report-update">Report</a><a class="card__metalink" href="${listingPageHref(x)}#share">Share</a></div></div></div></article>`}
function cardHTML(x){if(x.placeholder)return `<article class="card card--compact card--vacant" aria-label="Listing ${x.num} available"><div class="card__head"><span class="vacant-number">${x.num}</span><div class="card__heading"><h3 class="card__name">Listing number available</h3></div></div><div class="card__body"><p>This number is reserved for the next new listing.</p></div></article>`;if(isCommunity(x))return communityCardHTML(x);if(isTreatStop(x))return treatCardHTML(x);const selected=state.selected===x.num,onRoute=state.route.some(r=>r.num===x.num);return `<article class="card card--compact ${selected?'is-selected':''}${onRoute?' card--on-route':''}" data-card="${x.num}" data-town="${safeListingText(x.town)}" tabindex="0" aria-label="${safeListingText(x.name)}"><div class="card__head"><div class="card__pin">${cardIconHTML(isTreatStop(x)?'treat':'display')}</div><div class="card__heading"><h3 class="card__name"><span class="card__nametext" data-card-name="${x.num}">${safeListingText(x.name)}</span></h3></div></div>${listingStatusHTML(x)}<div class="card__addrline"><a class="card__address" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener" aria-label="Directions to ${safeListingText(x.name)}">${safeListingText(x.address.replace(/,\s*NJ\s*$/i,''))} ↗</a>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}</div><div class="card__hours-row"><p class="card__hours">${safeListingText(listingHoursText(x))}</p>${hasHostNotes(x)?`<details class="card__notes"><summary>Host notes</summary><div>${safeListingText(x.notes)}</div></details>`:''}${listingMediaHTML(x)}</div>${x.levels.length?`<p class="card__scare-row"><span class="card__scare">${scarePips(x.levels)}</span></p>`:''}${(x.type.length||x.features.length)?`<div class="card__tags">${x.type.map(t=>hfTagHTML(t,'chip--type')).join('')}${x.features.map(featureChip).join('')}</div>`:''}<div class="card__actions"><button class="btn card__route-btn" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button><button type="button" class="card__mapbtn" data-card-map="${x.num}"><span aria-hidden="true">◉</span> Map</button><button type="button" class="card__morebtn" data-card-more="${x.num}" aria-expanded="false" aria-label="More for ${safeListingText(x.name)}">⋯</button><div class="card__meta"><div class="card__meta-left"><a class="card-rating" href="${listingPageHref(x)}#feedback" data-rating-summary="${x.num}" aria-label="View ratings for ${safeListingText(x.name)}"><span class="card-rating__text">No ratings yet · <span class="card-rating__rate">Rate</span></span></a></div><div class="card__meta-right"><a class="card__metalink" href="${listingPageHref(x)}#report-update">Report</a><a class="card__metalink" href="${listingPageHref(x)}#share">Share</a></div></div></div></article>`}

function dateFilterChipsHTML(){
 const f=state.dateFilter||{};
 const chip=(kind,label)=>`<button type="button" class="filter filter--date" data-date-filter="${kind}" aria-pressed="${f.kind===kind}">${label}</button>`;
 const dateInput=f.kind==='date'?`<input type="date" id="dateFilterInput" class="filter-date-input" value="${safeListingText(f.date||'')}" aria-label="Choose a date">`:'';
 return `<div class="filter-tier filter-tier--date"><span class="filterbar__label">When</span>${chip('tonight','Tonight')}${chip('weekend','This weekend')}${chip('date','Choose a date')}${dateInput}</div>`;
}
function listingMediaHTML(x){const photos=(Array.isArray(x.photos)?x.photos:[]).filter(p=>typeof p==='string'&&p.startsWith('assets/')&&!p.includes('..'));const v=x.video&&typeof x.video==='object'?x.video:null;const src=v&&typeof v.src==='string'&&v.src.startsWith('assets/')&&!v.src.includes('..')?v.src:'';const poster=v&&typeof v.poster==='string'&&v.poster.startsWith('assets/')&&!v.poster.includes('..')?v.poster:'';if(!photos.length&&!src)return '';const imgs=photos.map(p=>`<img src="${safeListingText(p)}" alt="Photo of ${safeListingText(x.name)}" loading="lazy" decoding="async">`).join('');const vid=src?`<video controls muted playsinline preload="none"${poster?` poster="${safeListingText(poster)}"`:''} aria-label="Walkthrough of ${safeListingText(x.name)}"><source src="${safeListingText(src)}" type="video/mp4"></video>`:'';return `<details class="card__notes card__media"><summary>Photos</summary><div class="card__gallery">${imgs}${vid}</div></details>`}
function renderFilters(){const button=f=>`<button class="filter ${FEATURE_ICONS[f]?'filter--feature':''}" type="button" data-filter="${f}" aria-pressed="${state.filter===f}">${featureIcon(f)}${safeListingText(FEATURE_ICONS[f]?.label||f)}</button>`;const featureActive=filters.some(f=>FEATURE_ICONS[f]&&state.filter===f),anyActive=state.filter!=='All'||Boolean(state.dateFilter&&state.dateFilter.kind);document.getElementById('filters').innerHTML=`<div class="filter-tier filter-tier--primary"><span class="filterbar__label">Show</span>${filters.filter(f=>!FEATURE_ICONS[f]).map(button).join('')}${anyActive?'<button class="filter filter--reset" type="button" data-reset-filters>Reset filters</button>':''}</div><details class="filter-tier filter-tier--features"${featureActive?' open':''}><summary>Features</summary>${filters.filter(f=>FEATURE_ICONS[f]).map(button).join('')}</details>${dateFilterChipsHTML()}`}

function syncListingMarkers(visible){if(typeof L==='undefined'||!map||!markerByNum)return;const keep=new Set(visible.filter(x=>!x.placeholder&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)).map(x=>x.num));markerByNum.forEach((m,n)=>{const on=hasListing(m);if(keep.has(n)){if(!on)addListing(m)}else if(on)removeListing(m)})}
function renderCards(){const visible=activeListings();openTonightOK=typeof openTonightEligible==='function'&&typeof todayParts==='function'?openTonightEligible(visible,todayParts().dateStr):false;const geoEmpty=typeof geoEmptyState==='function'?geoEmptyState():null,noResults=document.getElementById('noResults'),nonPlaceholder=visible.filter(x=>!x.placeholder);noResults.dataset.mode=(!visible.length&&geoEmpty)?'geo':'';const noun=state.category==='treats'?'treat stop':'display',dateLabel=typeof dateFilterLabel==='function'?dateFilterLabel(state.dateFilter):null;document.getElementById('countLine').textContent=(state.search&&state.search.mode==='area'&&state.search.bounds?`${nonPlaceholder.length} ${noun}${nonPlaceholder.length===1?'':'s'} in this area`:state.search?(state.search.radius==='all'?`${nonPlaceholder.length} ${noun}${nonPlaceholder.length===1?'':'s'} in NJ`:`${nonPlaceholder.length} ${noun}${nonPlaceholder.length===1?'':'s'} within ${state.search.radius} mi`):`${nonPlaceholder.length} ${noun}${visible.length===1?'':'s'} shown`)+(state.filter!=='All'?' · '+state.filter:'')+(dateLabel?' · '+dateLabel:'');document.getElementById('cardList').innerHTML=visible.map(cardHTML).join('')+(state.category==='treats'&&visible.length?`<div class="treat-prompt"><p>Handing out candy on Halloween? Add your home so trick-or-treaters can find you.</p><a class="treat-prompt__link" href="${TREAT_FORM_URL}" target="_blank" rel="noopener">+ Add your home as a treat stop</a></div>`:'');syncListingMarkers(visible);noResults.classList.toggle('is-hidden',visible.length>0);const actionBtn=document.getElementById('emptyActionBtn');if(!visible.length&&geoEmpty){noResults.querySelector('strong').textContent=geoEmpty.headline;document.getElementById('noResultsText').textContent='';wireEmptyAction(geoEmpty,state.category==='treats'?TREAT_FORM_URL:FORM_URL)}else{document.getElementById('noResultsText').textContent=`No displays match “${state.filter}” right now.`;if(actionBtn)actionBtn.hidden=true}const te=document.getElementById('treatEmpty');if(te){const showTe=state.category==='treats'&&!visible.length&&!geoEmpty;te.classList.toggle('is-hidden',!showTe);if(showTe){te.innerHTML=`<img class="treat-empty__icon" src="assets/icons/pin-treat-stop.svg" alt="" width="40" height="47"><h3 class="treat-empty__title">${state.search&&state.search.radius==='all'?'No treat stops listed in NJ yet':`No treat stops listed within ${state.search?state.search.radius:25} mi yet`}</h3><p class="treat-empty__body">Handing out candy on Halloween? Add your home so trick-or-treaters can find you.</p><div class="treat-empty__actions"><button type="button" class="btn btn--route" data-treat-add>Add your home as a treat stop</button><button type="button" class="btn btn--outline" data-try-radius="50">Try 50 mi</button></div>`;te.querySelector('[data-treat-add]').onclick=()=>window.open(TREAT_FORM_URL,'_blank','noopener');te.querySelector('[data-try-radius]').onclick=()=>document.dispatchEvent(new CustomEvent('hf:expand-radius',{detail:{radius:50}}))}}markerByNum.forEach((m,n)=>{const x=listings.find(v=>v.num===n);if(x&&matchFilter(x)){if(!hasListing(m))addListing(m)}else if(hasListing(m))removeListing(m)});syncEventPins();wireCards()}
// Results rail: every matching card renders; pins and counts cover the same set.
function wireCards(){document.querySelectorAll('[data-card]').forEach(card=>{const n=+card.dataset.card;card.addEventListener('click',e=>{if(e.target.closest('button,a,details'))return;if(card.hasAttribute('data-community'))toggleCommunityCard(n);if(matchMedia('(max-width:1023px)').matches)return;selectListing(n,true)});card.addEventListener('keydown',e=>{if(e.target!==card||!['Enter',' '].includes(e.key))return;e.preventDefault();if(card.hasAttribute('data-community'))toggleCommunityCard(n);selectListing(n,true)});card.addEventListener('mouseenter',()=>linkPair(n,true));card.addEventListener('mouseleave',()=>linkPair(n,false));card.addEventListener('focus',()=>linkPair(n,true));card.addEventListener('blur',()=>linkPair(n,false))});document.querySelectorAll('[data-route]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleRoute(+b.dataset.route)});document.querySelectorAll('[data-community-toggle]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleCommunityCard(+b.dataset.communityToggle)})}
function linkPair(n,on){{const lm=markerByNum.get(n);if(lm&&listingCluster&&!lm.getElement()){const par=listingCluster.getVisibleParent(lm);par&&par.getElement&&par.getElement()&&par.getElement().classList.toggle('is-linked',on)}document.querySelector(`[data-card="${n}"]`)?.classList.toggle('is-linked',on);markerByNum.get(n)?.getElement()?.querySelector('.pin')?.classList.toggle('is-linked',on);raiseMarker(markerByNum.get(n),on||state.selected===n)}}
function selectListing(n,scroll=false){if(listings.find(x=>x.num===n)?.placeholder)return;state.selected=n;markerByNum.forEach((m,num)=>{m.getElement()?.querySelector('.pin')?.classList.toggle('is-selected',num===n);raiseMarker(m,num===n)});{const sm=markerByNum.get(n);if(sm)revealPin(sm,n)}document.querySelectorAll('[data-card]').forEach(c=>c.classList.toggle('is-selected',+c.dataset.card===n));renderPeek(n);if(scroll){const card=document.querySelector(`[data-card="${n}"]`);if(!card)return;const panel=card.closest('.list-column');if(panel&&panel.scrollHeight>panel.clientHeight){const pb=panel.getBoundingClientRect(),cb=card.getBoundingClientRect();if(cb.top>=pb.top&&cb.bottom<=pb.bottom)return;panel.scrollTo({top:Math.max(0,panel.scrollTop+cb.top-pb.top-Math.max(0,(panel.clientHeight-cb.height)/2)),behavior:'smooth'})}else if(innerWidth<1024)window.scrollTo({top:card.getBoundingClientRect().top+window.scrollY-Math.max(0,(innerHeight-card.offsetHeight)/2),behavior:'smooth'})}}
// K4 map popup (spec 8.7): one 280px popup at a time inside #mapPeek — photo
// slot (filled by loadPeekPhotos when photos exist), name, town · distance ·
// ★ rating, full-width add-to-route, × close.
function hidePeek(){document.getElementById('mapPeek').classList.add('is-hidden')}
function renderPeek(n){const x=listings.find(v=>v.num===n),peek=document.getElementById('mapPeek');if(!x||x.placeholder||!matchFilter(x)){hidePeek();return}if(isCommunity(x)){const onR=state.route.some(r=>r.num===n);peek.innerHTML=`<div class="map-popup map-popup--community" role="dialog" aria-label="${safeListingText(x.name)}"><button class="map-popup__close" type="button" aria-label="Close">×</button>${communityBodyHTML(x,true)}</div>`;peek.classList.remove('is-hidden');peek.querySelector('.map-popup__close').onclick=hidePeek;peek.querySelector('[data-peek-route]').onclick=()=>toggleRoute(n);return}const onRoute=state.route.some(r=>r.num===n),dist=state.search&&typeof haversineMi==='function'&&typeof formatDistance==='function'&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)?formatDistance(haversineMi(state.search,x))+' mi':'',rating=typeof ratingSummaries!=='undefined'?ratingSummaries.get(n):null,meta=[x.town,dist].filter(Boolean).join(' · ')+(rating&&rating.count?` · ★ ${rating.average}`:'');peek.innerHTML=`<div class="map-popup" role="dialog" aria-label="${safeListingText(x.name)}"><button class="map-popup__close" type="button" aria-label="Close">×</button><div class="map-popup__photo" data-peek-photo></div><div class="map-popup__body"><h3 class="map-popup__name">${safeListingText(x.name)}</h3><p class="map-popup__meta">${safeListingText(meta)}</p><button class="btn btn--route map-popup__add" type="button" data-peek-route="${n}" aria-pressed="${onRoute}">${onRoute?'✓ On your route':'+ Add to route'}</button><button type="button" class="map-popup__full" data-peek-full="${n}">Full details ▸</button></div></div>`;peek.classList.remove('is-hidden');typeof loadPeekPhotos==='function'&&loadPeekPhotos(n,x);peek.querySelector('.map-popup__close').onclick=hidePeek;peek.querySelector('[data-peek-route]').onclick=()=>toggleRoute(n)}
function toggleRoute(n){const listing=listings.find(x=>x.num===n);if(!listing||listing.placeholder)return;if(!state.route.some(r=>r.num===n)&&state.route.length>=10){state.routeMessage='Routes can have up to 10 stops.';renderRoute();return}state.routeMessage='';state.route=state.route.some(r=>r.num===n)?state.route.filter(r=>r.num!==n):[...state.route,{num:n,entityId:listing.entityId}];try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderCards();renderRoute();renderPeek(state.selected);markerByNum.forEach((m,num)=>m.getElement()?.querySelector('.pin')?.classList.toggle('is-on-route',state.route.some(r=>r.num===num)))}
// v5 Phase F: events join the shared route with a discriminated {eventId}
// entry (see routing.js). Same toggle pattern as listings; no map pins for
// events, so only the planner and cards re-render.
function toggleEventRoute(eventId){const ev=events.find(x=>x.id===eventId);if(!ev)return;if(!state.route.some(r=>r.eventId===eventId)&&state.route.length>=10){state.routeMessage='Routes can have up to 10 stops.';renderRoute();return}state.routeMessage='';state.route=toggleRouteEntry(state.route,{eventId:ev.id});try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderRoute();renderCards()}

// The route planner lives on /route.html (page-first plan step 4). The homepage
// keeps the shared hfroute:2026 route, the stop count, the cap/status message
// and same-tab links to the planner; the old route sheet and inline planner are gone.
function renderRoute(){const n=state.route.length,label=`${n} stop${n===1?'':'s'}`;const rc=document.getElementById('routeBarCount');if(rc){rc.textContent=String(n);rc.classList.toggle('is-zero',!n)}const rp=document.getElementById('routePanelCount');if(rp)rp.textContent=`${n} of 10 stops`;if(typeof syncRouteBadges==='function')syncRouteBadges();const status=document.getElementById('routeStatus');if(status)status.textContent=state.routeMessage||''}
// Back from /route.html can restore this page from the back/forward cache with
// the old route in memory: re-read the shared store so counts and cards match.
window.addEventListener('pageshow',e=>{if(!e.persisted)return;state.route=loadSavedRoute(localStorage,listings,events);state.routeMessage='';renderCards();renderRoute();renderPeek(state.selected)});

// Fit the map to the current tab's pins: one pin centres at zoom 14; several fit with room for the route bar.
function fitVisiblePins(){if(typeof L==='undefined'||!map)return;const pts=activeListings().filter(x=>!x.placeholder&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)).map(x=>[x.lat,x.lng]);if(!pts.length)return;if(pts.length===1)map.setView(pts[0],14,{animate:false});else map.fitBounds(pts,mapFitOptions({maxZoom:15,animate:false}))}
function revealPin(m,n){if(!listingCluster||!hasListing(m)||m.getElement())return;map.setView(m.getLatLng(),Math.max(map.getZoom(),CLUSTER_STOP_ZOOM),{animate:false});const par=listingCluster.getVisibleParent(m);if(par&&par!==m&&par.spiderfy)par.spiderfy();setTimeout(()=>applyPinState(m,n),60)}
function revealSelectedPin(){if(state.selected==null)return;const sm=markerByNum.get(state.selected);if(sm)revealPin(sm,state.selected)}
async function loadMarkers(){const bounds=[];for(const x of listings){if(x.placeholder||!Number.isFinite(x.lat)||!Number.isFinite(x.lng))continue;const c={lat:x.lat,lng:x.lng};state.coords[x.num]=c;const m=L.marker([c.lat,c.lng],{icon:iconFor(x.num,isCommunity(x)?'community':isTreatStop(x)?'treat':'display'),keyboard:true,title:`${isCommunity(x)?'Community-spotted display':isTreatStop(x)?'Treat stop':'Display'}: ${x.name}`,zIndexOffset:(listings.filter(v=>v.address===x.address).length>1?1000:100)+x.num});m.on('add',()=>applyPinState(m,x.num));addListing(m);m.getElement()?.setAttribute('aria-label',`${isCommunity(x)?'Community-spotted display':isTreatStop(x)?'Treat stop':'Display'}: ${x.name}`);m.on('click',()=>{selectListing(x.num,true)});m.on('mouseover',()=>linkPair(x.num,true));m.on('mouseout',()=>linkPair(x.num,false));markerByNum.set(x.num,m);bounds.push([c.lat,c.lng])}if(bounds.length)fitVisiblePins();[100,600,1500].forEach(t=>setTimeout(()=>{map.invalidateSize();revealSelectedPin()},t))}

document.getElementById('filters').addEventListener('click',e=>{if(e.target.closest('[data-reset-filters]')){state.filter='All';state.dateFilter=typeof saveDateFilter==='function'?saveDateFilter({kind:null,date:null},localStorage):null;renderFilters();renderCards();return}const b=e.target.closest('[data-filter]');if(!b)return;state.filter=state.filter===b.dataset.filter?'All':b.dataset.filter;renderFilters();renderCards()});document.getElementById('showAllBtn').onclick=()=>{state.filter='All';state.features=[];state.dateFilter=typeof saveDateFilter==='function'?saveDateFilter({kind:null,date:null},localStorage):null;renderFilters();renderCards()};document.getElementById('shareBtn').onclick=async()=>{const b=document.getElementById('shareBtn'),payload={title:'Hauntfinder',text:'Find Halloween displays, treat stops, and events near you.',url:'https://hauntfinder.vercel.app/'};try{if(navigator.share)await navigator.share(payload);else{await navigator.clipboard.writeText('https://hauntfinder.vercel.app/');b.textContent='Link copied';setTimeout(()=>b.textContent='Share this site',2000)}}catch{}};
renderFilters();renderCards();renderRoute();loadMarkers();


